"""UGEN kernel — generated by push_kernel.py; do not edit by hand."""
import os
import sys

# locate the ugen package and the frozen data regardless of how Kaggle unpacked the zips
src_root, data_dir = None, None
for dp, dns, fns in os.walk("/kaggle/input"):
    if "runner.py" in fns and dp.replace("\\", "/").endswith("ugen/pipeline"):
        src_root = os.path.dirname(os.path.dirname(dp))
    if "mmlu.jsonl" in fns and "MANIFEST.json" in fns:
        data_dir = dp
if src_root is None or data_dir is None:
    listing = [os.path.join(dp, f) for dp, _, fns in os.walk("/kaggle/input")
               for f in fns][:80]
    raise SystemExit(f"layout not found: src={src_root} data={data_dir}; saw {listing}")
sys.path.insert(0, src_root)
print(f"src={src_root} data={data_dir}", flush=True)

from ugen.pipeline.runner import main

main(model_hint='3b-instruct', model_name='Qwen2.5-3B-Instruct',
     benchmarks=['mmlu', 'mmlu_pro', 'truthfulqa', 'gpqa', 'gsm8k', 'svamp', 'multiarith', 'commonsenseqa', 'arc_challenge', 'strategyqa', 'bbh', 'musr', 'humaneval', 'mbpp'],
     data_dir=data_dir,
     seed=0, limit=8)
